export interface Invoice {
  id: string;
  invoiceNumber: string;
  total: number;
  issuedAt: string;
}

function isInvoice(obj: unknown): obj is Invoice {
  return (
    typeof obj === 'object' &&
    obj !== null &&
    'id' in obj &&
    'invoiceNumber' in obj &&
    'total' in obj &&
    'issuedAt' in obj &&
    typeof (obj as Record<string, unknown>).id === 'string' &&
    typeof (obj as Record<string, unknown>).invoiceNumber === 'string' &&
    typeof (obj as Record<string, unknown>).total === 'number' &&
    typeof (obj as Record<string, unknown>).issuedAt === 'string'
  );
}

export async function fetchInvoices(): Promise<Invoice[]> {
  const response = await fetch('/api/invoices');
  const data = await response.json();

  if (!Array.isArray(data)) {
    throw new Error('Expected array of invoices');
  }

  if (!data.every(isInvoice)) {
    throw new Error('Invalid invoice data');
  }

  return data;
}

